            C++

    #include <iostream>
using namespace std;

bool isPerfectCube(int num)
{
    long left = 0;
    long right = num;
    while (left <= right) {
        long mid = left + (right - left) / 2;
        long cube = mid * mid * mid;
        if (cube == num) {
            return true;
        }
        else if (cube < num) {
            left = mid + 1;
        }
        else {
            right = mid - 1;
        }
    }
    return false;
}

int main()
{
    if (isPerfectCube(729))
        cout << "Yes" << endl;
    else
        cout << "No" << endl;

    return 0;
}


